//! The Markdown walkthrough of the catalog.

use helixforge_core::{Item, Tab};

pub fn walkthrough(tabs: &[Tab]) -> String {
    let mut text = String::from(
        "<!-- Generated by helixforge docgen; do not edit by hand. -->\n# Walkthrough\n",
    );
    for tab in tabs {
        text.push_str(&format!("\n## {}\n\n", tab.name));
        items(&tab.items, &mut text);
    }
    text
}

fn items(list: &[Item], text: &mut String) {
    for item in list {
        match item {
            Item::Group(group) => {
                text.push_str(&format!("\n### {}\n\n", group.name));
                if !group.description.is_empty() {
                    text.push_str(&format!("{}\n\n", group.description));
                }
                items(&group.items, text);
            }
            Item::Entry(entry) if !entry.description.is_empty() => {
                text.push_str(&format!("- **{}**: {}\n", entry.name, entry.description));
            }
            Item::Entry(_) => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use helixforge_core::{Action, Entry, Group};

    #[test]
    fn groups_become_headings_and_described_entries_bullets() {
        let entry = |name: &str, description: &str| {
            Item::Entry(Entry {
                id: name.to_lowercase(),
                name: name.into(),
                description: description.into(),
                flags: String::new(),
                multi_select: true,
                action: Action::Command {
                    line: "true".into(),
                },
            })
        };
        let tab = Tab {
            id: "apps".into(),
            name: "Apps".into(),
            items: vec![
                Item::Group(Group {
                    id: "browsers".into(),
                    name: "Browsers".into(),
                    description: String::new(),
                    multi_select: true,
                    items: vec![entry("Brave", "A browser.")],
                }),
                entry("Quiet", ""),
            ],
        };
        let text = walkthrough(&[tab]);
        assert!(text.contains("## Apps\n"));
        assert!(text.contains("### Browsers\n"));
        assert!(text.contains("- **Brave**: A browser.\n"));
        assert!(!text.contains("Quiet"));
    }
}
